<script setup>
import {computed,onMounted,ref,watch} from 'vue';
const items=ref([]),season=ref(''),loading=ref(true),error=ref(''),page=ref(1),total=ref(0),availableSeasons=ref([]);let requestId=0;
const current=`${new Date().getFullYear()}-Q${Math.floor(new Date().getMonth()/3)+1}`;
const seasons=computed(()=>[...new Set([current,...availableSeasons.value])].sort().reverse());
const day=ref('all'),weekdays=['一','二','三','四','五','六','日'],today=weekdays[(new Date().getDay()+6)%7];
function weekday(value){const m=String(value||'').match(/(?:周|星期|礼拜)([一二三四五六日天])/);return m?(m[1]==='天'?'日':m[1]):'';}
const filtered=computed(()=>items.value);
async function load(){const id=++requestId;loading.value=true;error.value='';try{const params=new URLSearchParams({season:season.value,weekday:day.value==='all'?'':day.value,page:String(page.value),pageSize:'24'});const r=await fetch('/api/public/catalog/anime?'+params);if(!r.ok)throw Error('海报暂时没有加载成功');const data=await r.json();if(id!==requestId)return;items.value=data.items;total.value=data.total;availableSeasons.value=data.seasons;}catch(e){if(id===requestId)error.value=e.message;}finally{if(id===requestId)loading.value=false;}}
function fallback(e){if(!e.target.src.endsWith('/assets/flower-03.webp'))e.target.src='/assets/flower-03.webp';}
season.value=current;
watch([season,day],()=>{page.value=1;load();});
onMounted(load);
</script>
<style scoped>.week-filter{display:flex;gap:8px;flex-wrap:wrap;margin:-16px 0 28px}.week-filter small{font-size:10px}</style>
<template><main class="public-anime"><header><span>SEASONAL SCREENING / 季度放映室</span><h1>把喜欢的故事，留在这一季。</h1><p>一面随季节更新的海报墙，收藏那些想认真看完的故事。</p></header><nav aria-label="番剧季度"><button v-for="q in seasons" :key="q" :class="{active:season===q}" @click="season=q">{{q.replace('-Q',' · 第 ')}} 季度</button><button v-if="items.some(x=>!x.season)" :class="{active:season===''}" @click="season=''">待整理</button></nav><div class="week-filter" aria-label="按播出星期筛选"><button :class="{active:day==='all'}" @click="day='all'">全部</button><button v-for="d in weekdays" :key="d" :class="{active:day===d}" @click="day=d">周{{d}}<small v-if="d===today"> · 今天</small></button><button :class="{active:day==='unknown'}" @click="day='unknown'">待定</button></div><p v-if="loading" class="wall-message" role="status">正在布置放映室…</p><div v-else-if="error" class="wall-message" role="alert">{{error}} <button @click="load">重试</button></div><div v-else-if="filtered.length" class="public-posters"><article v-for="(item,index) in filtered" :key="item.id" :style="{'--delay':Math.min(index,10)*35+'ms'}"><div class="poster-image"><img :src="item.cover" :alt="item.title" loading="lazy" @error="fallback"/><span>{{String(index+1).padStart(2,'0')}}</span></div><small>{{item.broadcast||item.season||'播出时间待更新'}}</small><h2>{{item.title}}</h2><p>{{item.tags||item.creator||'这一季的故事'}}</p></article></div><div v-else class="wall-message"><h2>这一季，留一点期待。</h2><p>站主还没有公开这一季度的番剧。</p></div><nav v-if="total>24" aria-label="海报分页"><button :disabled="page<=1" @click="page--;load()">上一页</button><span>{{page}} / {{Math.ceil(total/24)}} · 共 {{total}} 部</span><button :disabled="page*24>=total" @click="page++;load()">下一页</button></nav></main></template>
<style scoped>
.public-anime{max-width:1240px;margin:110px auto 70px;padding:0 32px;color:var(--lin-text)}header{padding:40px 0 34px;border-bottom:1px solid var(--lin-line)}header>span{font-size:11px;letter-spacing:3px;color:var(--lin-accent)}h1{font-size:clamp(26px,4vw,44px);line-height:1.4;margin:20px 0}header p,.wall-message p{color:var(--lin-muted);line-height:1.8}nav{display:flex;gap:10px;flex-wrap:wrap;padding:25px 0 35px}button{border:1px solid var(--lin-line);background:var(--lin-paper);color:inherit;padding:10px 16px;border-radius:6px;cursor:pointer}button.active{background:var(--lin-accent);color:white}.public-posters{display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:32px 22px}.public-posters article{animation:poster-enter .5s both;animation-delay:var(--delay);min-width:0}.poster-image{aspect-ratio:2/3;overflow:hidden;position:relative;border-radius:8px;background:var(--lin-line);box-shadow:0 10px 28px #16132718}.poster-image img{width:100%;height:100%;object-fit:cover;transition:transform .45s}.poster-image:hover img{transform:scale(1.045)}.poster-image>span{position:absolute;bottom:10px;left:12px;color:white;font:italic 32px Georgia;text-shadow:0 2px 8px #000}.public-posters small{display:block;margin-top:16px;color:var(--lin-accent);font-size:10px;letter-spacing:1px}.public-posters h2{font-size:16px;line-height:1.6;margin:6px 0}.public-posters p{font-size:11px;color:var(--lin-muted);line-height:1.6}.wall-message{text-align:center;padding:70px 15px;border:1px dashed var(--lin-line);border-radius:10px}@keyframes poster-enter{from{opacity:0;transform:translateY(16px)}to{opacity:1;transform:none}}@media(max-width:600px){.public-anime{padding:0 20px;margin-top:85px}.public-posters{grid-template-columns:repeat(2,minmax(0,1fr));gap:24px 14px}}@media(prefers-reduced-motion:reduce){.public-posters article{animation:none}.poster-image img{transition:none}}
</style>
